package Q7;
import java.nio.file.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public class BatchProcessor{record Result(Path file,boolean ok,String message){}static Result process(Path p){try{try(BufferedReader r=Files.newBufferedReader(p)){long n=r.lines().count();return new Result(p,true,"lines="+n);}}catch(Exception e){return new Result(p,false,e.getClass().getSimpleName()+": "+e.getMessage());}}public static void main(String[]x)throws Exception{Path d=Files.createTempDirectory("batch");List<Path>fs=new ArrayList<>();for(int i=0;i<10;i++){Path p=d.resolve("f"+i+".txt");if(i!=4)Files.writeString(p,"one\\ntwo\\n");fs.add(p);}for(int pool:new int[]{1,2,4,8}){long t=System.nanoTime();ExecutorService ex=Executors.newFixedThreadPool(pool);try{List<Future<Result>>f=new ArrayList<>();for(Path p:fs)f.add(ex.submit(()->process(p)));int ok=0,bad=0;for(Future<Result>v:f)if(v.get().ok())ok++;else bad++;System.out.println("pool="+pool+" success="+ok+" failed="+bad+" ns="+(System.nanoTime()-t));}finally{ex.shutdown();}}}}
